// ServerInterface represents all server handlers.
type ServerInterface interface {
	// ListAudit Read the audit trail (audit.view)
	// (GET /api/v1/audit)
	ListAudit(w http.ResponseWriter, r *http.Request, params ListAuditParams)
	// Login Log in with username and password (and TOTP when enabled)
	// (POST /api/v1/auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout End the current browser session
	// (POST /api/v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// ListCameraGroups List camera groups
	// (GET /api/v1/camera-groups)
	ListCameraGroups(w http.ResponseWriter, r *http.Request)
	// CreateCameraGroup Create a camera group
	// (POST /api/v1/camera-groups)
	CreateCameraGroup(w http.ResponseWriter, r *http.Request)
	// DeleteCameraGroup Delete a camera group
	// (DELETE /api/v1/camera-groups/{groupId})
	DeleteCameraGroup(w http.ResponseWriter, r *http.Request, groupId openapi_types.UUID)
	// GetCameraGroup Get a camera group
	// (GET /api/v1/camera-groups/{groupId})
	GetCameraGroup(w http.ResponseWriter, r *http.Request, groupId openapi_types.UUID)
	// ReplaceCameraGroup Replace name, description and members of a camera group
	// (PUT /api/v1/camera-groups/{groupId})
	ReplaceCameraGroup(w http.ResponseWriter, r *http.Request, groupId openapi_types.UUID)
	// ListCameras List cameras the caller can view
	// (GET /api/v1/cameras)
	ListCameras(w http.ResponseWriter, r *http.Request, params ListCamerasParams)
	// GetCamera Get a camera
	// (GET /api/v1/cameras/{cameraId})
	GetCamera(w http.ResponseWriter, r *http.Request, cameraId openapi_types.UUID)
	// UpdateCamera Rename or enable/disable a camera in the VMS
	// (PATCH /api/v1/cameras/{cameraId})
	UpdateCamera(w http.ResponseWriter, r *http.Request, cameraId openapi_types.UUID)
	// ListCameraRecordings Recorded spans of a camera, read from its Frigate (recordings.seek)
	// (GET /api/v1/cameras/{cameraId}/recordings)
	ListCameraRecordings(w http.ResponseWriter, r *http.Request, cameraId openapi_types.UUID, params ListCameraRecordingsParams)
	// ListEvents Search the federated event index
	// (GET /api/v1/events)
	ListEvents(w http.ResponseWriter, r *http.Request, params ListEventsParams)
	// ListEventSyncStatus Event ingestion state per Frigate server
	// (GET /api/v1/events/sync-status)
	ListEventSyncStatus(w http.ResponseWriter, r *http.Request)
	// GetEvent Get an event
	// (GET /api/v1/events/{eventId})
	GetEvent(w http.ResponseWriter, r *http.Request, eventId openapi_types.UUID)
	// UpdateEvent Mark an event reviewed or not (events.review)
	// (PATCH /api/v1/events/{eventId})
	UpdateEvent(w http.ResponseWriter, r *http.Request, eventId openapi_types.UUID)
	// GetEventThumbnail Event thumbnail
	// (GET /api/v1/events/{eventId}/thumbnail)
	GetEventThumbnail(w http.ResponseWriter, r *http.Request, eventId openapi_types.UUID)
	// ListExports Your exports and those of cameras where you hold exports.download
	// (GET /api/v1/exports)
	ListExports(w http.ResponseWriter, r *http.Request)
	// CreateExport Export a clip from the camera's Frigate (exports.create)
	// (POST /api/v1/exports)
	CreateExport(w http.ResponseWriter, r *http.Request)
	// DeleteExport Remove an export from the VMS list (the file in Frigate is untouched)
	// (DELETE /api/v1/exports/{exportId})
	DeleteExport(w http.ResponseWriter, r *http.Request, exportId openapi_types.UUID)
	// GetExport Get an export
	// (GET /api/v1/exports/{exportId})
	GetExport(w http.ResponseWriter, r *http.Request, exportId openapi_types.UUID)
	// ListGrants List grants
	// (GET /api/v1/grants)
	ListGrants(w http.ResponseWriter, r *http.Request, params ListGrantsParams)
	// CreateGrant Grant or deny a permission on a scope
	// (POST /api/v1/grants)
	CreateGrant(w http.ResponseWriter, r *http.Request)
	// DeleteGrant Revoke a grant
	// (DELETE /api/v1/grants/{grantId})
	DeleteGrant(w http.ResponseWriter, r *http.Request, grantId openapi_types.UUID)
	// ListUserGroups List user groups (groups.view)
	// (GET /api/v1/groups)
	ListUserGroups(w http.ResponseWriter, r *http.Request, params ListUserGroupsParams)
	// CreateUserGroup Create a user group (groups.manage)
	// (POST /api/v1/groups)
	CreateUserGroup(w http.ResponseWriter, r *http.Request)
	// DeleteUserGroup Delete a user group (its grants stop applying)
	// (DELETE /api/v1/groups/{groupId})
	DeleteUserGroup(w http.ResponseWriter, r *http.Request, groupId openapi_types.UUID)
	// GetUserGroup Get a user group
	// (GET /api/v1/groups/{groupId})
	GetUserGroup(w http.ResponseWriter, r *http.Request, groupId openapi_types.UUID)
	// ReplaceUserGroup Rename a group and replace its members
	// (PUT /api/v1/groups/{groupId})
	ReplaceUserGroup(w http.ResponseWriter, r *http.Request, groupId openapi_types.UUID)
	// ListPlateReads Search plate reads across every authorized Frigate
	// (GET /api/v1/lpr/reads)
	ListPlateReads(w http.ResponseWriter, r *http.Request, params ListPlateReadsParams)
	// GetMe Current user and their permissions
	// (GET /api/v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// DisableMfa Turn MFA off (needs the password)
	// (POST /api/v1/me/mfa/disable)
	DisableMfa(w http.ResponseWriter, r *http.Request)
	// EnableMfa Confirm a TOTP code and turn MFA on
	// (POST /api/v1/me/mfa/enable)
	EnableMfa(w http.ResponseWriter, r *http.Request)
	// SetupMfa Start TOTP enrolment
	// (POST /api/v1/me/mfa/setup)
	SetupMfa(w http.ResponseWriter, r *http.Request)
	// ChangePassword Change your own password
	// (POST /api/v1/me/password)
	ChangePassword(w http.ResponseWriter, r *http.Request)
	// ListPermissionCatalog Permission catalog
	// (GET /api/v1/permissions)
	ListPermissionCatalog(w http.ResponseWriter, r *http.Request)
	// ListServers List Frigate servers the caller can view
	// (GET /api/v1/servers)
	ListServers(w http.ResponseWriter, r *http.Request, params ListServersParams)
	// CreateServer Register a Frigate server
	// (POST /api/v1/servers)
	CreateServer(w http.ResponseWriter, r *http.Request)
	// ProbeServer Test a Frigate connection without saving it
	// (POST /api/v1/servers/probe)
	ProbeServer(w http.ResponseWriter, r *http.Request)
	// DeleteServer Remove a server and its cameras from the VMS (soft delete)
	// (DELETE /api/v1/servers/{serverId})
	DeleteServer(w http.ResponseWriter, r *http.Request, serverId openapi_types.UUID)
	// GetServer Get a Frigate server
	// (GET /api/v1/servers/{serverId})
	GetServer(w http.ResponseWriter, r *http.Request, serverId openapi_types.UUID)
	// UpdateServer Rename, move or change the credentials of a server
	// (PATCH /api/v1/servers/{serverId})
	UpdateServer(w http.ResponseWriter, r *http.Request, serverId openapi_types.UUID)
	// SyncServer Rediscover version, capabilities and cameras
	// (POST /api/v1/servers/{serverId}/sync)
	SyncServer(w http.ResponseWriter, r *http.Request, serverId openapi_types.UUID)
	// ListSites List sites the caller can view
	// (GET /api/v1/sites)
	ListSites(w http.ResponseWriter, r *http.Request, params ListSitesParams)
	// CreateSite Create a site
	// (POST /api/v1/sites)
	CreateSite(w http.ResponseWriter, r *http.Request)
	// DeleteSite Soft-delete an empty site
	// (DELETE /api/v1/sites/{siteId})
	DeleteSite(w http.ResponseWriter, r *http.Request, siteId openapi_types.UUID)
	// GetSite Get a site
	// (GET /api/v1/sites/{siteId})
	GetSite(w http.ResponseWriter, r *http.Request, siteId openapi_types.UUID)
	// UpdateSite Update a site
	// (PATCH /api/v1/sites/{siteId})
	UpdateSite(w http.ResponseWriter, r *http.Request, siteId openapi_types.UUID)
	// GetSystemInfo Build and runtime information
	// (GET /api/v1/system/info)
	GetSystemInfo(w http.ResponseWriter, r *http.Request)
	// ListTenants List tenants visible to the caller
	// (GET /api/v1/tenants)
	ListTenants(w http.ResponseWriter, r *http.Request)
	// CreateTenant Create a tenant (platform administrators)
	// (POST /api/v1/tenants)
	CreateTenant(w http.ResponseWriter, r *http.Request)
	// ListUsers List users (users.view)
	// (GET /api/v1/users)
	ListUsers(w http.ResponseWriter, r *http.Request, params ListUsersParams)
	// CreateUser Create a user (users.manage; groups.manage to add groups)
	// (POST /api/v1/users)
	CreateUser(w http.ResponseWriter, r *http.Request)
	// DeleteUser Remove a user (soft delete, sessions closed)
	// (DELETE /api/v1/users/{userId})
	DeleteUser(w http.ResponseWriter, r *http.Request, userId openapi_types.UUID)
	// GetUser Get a user
	// (GET /api/v1/users/{userId})
	GetUser(w http.ResponseWriter, r *http.Request, userId openapi_types.UUID)
	// UpdateUser Update, disable, reset the password or MFA of a user (users.manage)
	// (PATCH /api/v1/users/{userId})
	UpdateUser(w http.ResponseWriter, r *http.Request, userId openapi_types.UUID)
	// ListViews Your views and the shared views of your tenant
	// (GET /api/v1/views)
	ListViews(w http.ResponseWriter, r *http.Request)
	// CreateView Save a view (views.create_private, or views.create_shared when shared)
	// (POST /api/v1/views)
	CreateView(w http.ResponseWriter, r *http.Request)
	// DeleteView Delete a view
	// (DELETE /api/v1/views/{viewId})
	DeleteView(w http.ResponseWriter, r *http.Request, viewId openapi_types.UUID)
	// GetView Get a view
	// (GET /api/v1/views/{viewId})
	GetView(w http.ResponseWriter, r *http.Request, viewId openapi_types.UUID)
	// ReplaceView Change a view (owner, or views.manage_shared for shared views)
	// (PUT /api/v1/views/{viewId})
	ReplaceView(w http.ResponseWriter, r *http.Request, viewId openapi_types.UUID)
	// GetLiveness Liveness probe
	// (GET /health/live)
	GetLiveness(w http.ResponseWriter, r *http.Request)
	// GetReadiness Readiness probe
	// (GET /health/ready)
	GetReadiness(w http.ResponseWriter, r *http.Request)
}

